import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> {'side':..., 'price':..., 'qty':..., 'active': bool}
    seq_counter = 0

    def match_incoming(side, price, qty, incoming_id):
        # price is None for market orders (matches any price)
        nonlocal buy_heap, sell_heap
        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while qty > 0 and heap:
            top = heap[0]
            if side == 'buy':
                top_price, top_seq, top_id = top
            else:
                neg_price, top_seq, top_id = top
                top_price = -neg_price

            # check if still active
            info = book.get(top_id)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue

            # check price crossing
            if price is not None:
                if side == 'buy':
                    if top_price > price:
                        break
                else:
                    if top_price < price:
                        break

            # match
            heapq.heappop(heap)
            resting_qty = info['qty']
            trade_qty = min(qty, resting_qty)

            if side == 'buy':
                buy_id = incoming_id
                sell_id = top_id
            else:
                buy_id = top_id
                sell_id = incoming_id

            trades.append([buy_id, sell_id, top_price, trade_qty])

            qty -= trade_qty
            info['qty'] -= trade_qty

            if info['qty'] > 0:
                # push back
                if side == 'buy':
                    heapq.heappush(heap, (top_price, top_seq, top_id))
                else:
                    heapq.heappush(heap, (-top_price, top_seq, top_id))
            else:
                info['active'] = False

        return qty

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            _, oid = order
            info = book.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, oid)
            if remaining > 0:
                book[oid] = {'side': side, 'price': price, 'qty': remaining, 'active': True}
                seq_counter += 1
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq_counter, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq_counter, oid))
            else:
                # fully filled, still record in book as inactive for id uniqueness tracking
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, oid)
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}

        elif typ == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(side, None, qty, oid)
            book[oid] = {'side': side, 'price': None, 'qty': 0, 'active': False}

    return trades

